// FR-10 — Generate CITATION.cff (GitHub's native software citation format)
// from package.json, the single source of truth. Runs locally and in CI
// (the release workflow attaches the generated file to the GitHub release).
//
// Usage:  node scripts/gen-citation-cff.mjs [--out <path>]
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const pkg = JSON.parse(readFileSync(path.join(ROOT, 'package.json'), 'utf8'));

// Repository URL: prefer package.json repository field, fall back to the
// canonical upstream repo used across the app.
const repo =
  typeof pkg.repository === 'string'
    ? pkg.repository
    : (pkg.repository?.url ?? '').replace(/^git\+/, '').replace(/\.git$/, '') ||
      'https://github.com/SnowLeopard-io/ErgalicsStudio';

// Author may be "Name <email>" or an object.
const authorStr =
  typeof pkg.author === 'string'
    ? pkg.author
    : `${pkg.author?.name ?? ''}${pkg.author?.email ? ` <${pkg.author.email}>` : ''}`;
const authorMatch = /^(.*?)\s*<(.+)>$/.exec(authorStr);
const authorName = (authorMatch?.[1] ?? authorStr).trim();
const authorEmail = authorMatch?.[2]?.trim() ?? '';

function titleCase(name) {
  return name
    .split(/[-_]/)
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
    .join(' ');
}

function esc(s) {
  return String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"');
}

const lines = [
  '# YAML 1.2',
  '# Generated by scripts/gen-citation-cff.mjs from package.json — do not edit by hand.',
  'cff-version: 1.2.0',
  'message: "If you use this software, please cite it as below."',
  `title: "${esc(titleCase(pkg.name))}"`,
  `version: "${esc(pkg.version)}"`,
  `date-released: "${new Date().toISOString().slice(0, 10)}"`,
  `repository-code: "${esc(repo)}"`,
  `license: "${esc(pkg.license ?? 'MIT')}"`,
  'authors:',
  `  - family-names: "${esc(authorName)}"`,
];
if (authorEmail) lines.push(`    email: "${esc(authorEmail)}"`);
if (pkg.description) lines.push(`abstract: "${esc(pkg.description)}"`);
lines.push('keywords:');
lines.push('  - "scientific computing"');
lines.push('  - "webgpu"');
lines.push('  - "browser"');

const cff = lines.join('\n') + '\n';

const outArgIdx = process.argv.indexOf('--out');
const outArg = outArgIdx !== -1 ? process.argv[outArgIdx + 1] : undefined;
const outPath = outArg ? path.resolve(process.cwd(), outArg) : path.join(ROOT, 'CITATION.cff');

writeFileSync(outPath, cff, 'utf8');
console.log(`gen-citation-cff: wrote ${outPath} (version ${pkg.version})`);
